    gtcSum: m.gtcSum ?? m.efcSum, efcSum: m.efcSum, fceSum: m.fceSum, rfEfcSum: m.rfEfcSum, grossThroughputKwh: m.grossThroughputKwh, daysSpan: m.daysSpan,
    metricConvention: A.metricConvention || null,
