    // round-2: overview / methodology aggregates (generated, master-derived)
    loggedDates: m.loggedDates, movingHours: m.movingHours, stationaryHours: m.stationaryHours, stationaryCoverageN: m.stationaryCoverageN,
    deficitValidN: m.deficitValidN, deficitMeanPct: m.deficitMeanPct, deficitMinPct: m.deficitMinPct, deficitMaxPct: m.deficitMaxPct,
    // M41 (2026-07-17): engine-on discharge-share decomposition (blend vs
