  const nm=(k)=>{ const m=/^(movingBlock|hac)L(\d+)$/.exec(k); return m ? (m[1]==="hac" ? `HAC ${m[2]}-day` : `${m[2]}-day moving-block`) : k; };
  const inc=rr.rowsIncludingZero||[], exc=rr.rowsExcludingZero||[];
